const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体示意（非按比例）' },
      { kind: 'text', payload: '静止释放  v₀ = 0' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v、g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var ball = visualSdk.circle(260, 135, 26);
    var vArrow = visualSdk.arrow(305, 190, 305, 300, {});
    var gArrow = visualSdk.arrow(215, 190, 215, 300, {});
    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'ball', commands: ball },
        { id: 'v', commands: vArrow },
        { id: 'g', commands: gArrow }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ball', fill: '#9ecae1', stroke: { width: 2 } },
          { type: 'path', pathId: 'v', fill: '#c0392b', stroke: { width: 2 } },
          { type: 'path', pathId: 'g', fill: '#2c3e50', stroke: { width: 2 } },
          { type: 'label', contentId: 'c0', anchor: { x: 260, y: 40 }, hAlign: 'center', vAlign: 'middle', color: '#1f2d3d' },
          { type: 'label', contentId: 'c1', anchor: { x: 260, y: 88 }, hAlign: 'center', vAlign: 'middle', color: '#1f2d3d' },
          { type: 'label', contentId: 'c2', anchor: { x: 315, y: 245 }, hAlign: 'left', vAlign: 'middle', color: '#c0392b' },
          { type: 'label', contentId: 'c3', anchor: { x: 205, y: 245 }, hAlign: 'right', vAlign: 'middle', color: '#2c3e50' },
          { type: 'label', contentId: 'c4', anchor: { x: 260, y: 335 }, hAlign: 'center', vAlign: 'middle', color: '#1f2d3d' }
        ]
      }
    };
  }
};
